<?php
// Panel de cuenta del proyecto original, alimentado por PostgreSQL.
if (!isset($usuario) || !is_array($usuario)) { http_response_code(403); exit('Sesión requerida'); }
require_once __DIR__.'/../../config/database.php';
$db = (new Database())->connect();
$id = (int)$usuario['id_usuario'];
$esc = static fn($v): string => htmlspecialchars((string)($v ?? ''), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
$pedidos = $db->prepare('SELECT id_pedido, fecha_pedido, estado_pedido, total FROM pedido WHERE id_usuario = :id ORDER BY fecha_pedido DESC NULLS LAST, id_pedido DESC LIMIT 15');
$pedidos->execute(['id'=>$id]);
$misPedidos = $pedidos->fetchAll(PDO::FETCH_ASSOC);
$eventos = $db->prepare('SELECT e.id_evento, e.fecha_hora, e.tipo_evento, e.lugar_direccion, p.nombre_paquete, r.estado_reserva FROM evento e JOIN paquete p ON p.id_paquete=e.id_paquete LEFT JOIN reserva r ON r.id_evento=e.id_evento WHERE e.id_usuario=:id ORDER BY e.fecha_hora DESC LIMIT 15');
$eventos->execute(['id'=>$id]);
$misEventos = $eventos->fetchAll(PDO::FETCH_ASSOC);
$direcciones = $db->prepare('SELECT id_direccion, calle_numero, colonia, ciudad, codigo_postal, referencias FROM direccion WHERE id_usuario=:id ORDER BY id_direccion DESC');
$direcciones->execute(['id'=>$id]);
$misDirecciones = $direcciones->fetchAll(PDO::FETCH_ASSOC);
$nombre = trim((string)$usuario['nombre_completo']);
$primera = mb_strtoupper(mb_substr($nombre,0,1));
$mensaje = $_SESSION['mensaje_perfil'] ?? null; unset($_SESSION['mensaje_perfil']);
?>
