<main><div class="hero"><div class="avatar" aria-label="Inicial del usuario"><?= $esc($primera) ?></div><div><h1>Hola, <?= $esc($nombre) ?></h1><p class="muted">Tu cuenta · <?= $esc($usuario['correo']) ?> · <?= $esc($usuario['rol']) ?></p></div></div>
<?php if($mensaje): ?><div role="status" class="notice <?= ($mensaje['tipo']??'')==='error'?'error':'' ?>"><?= $esc($mensaje['texto']??'') ?></div><?php endif; ?>
<div class="grid"><section class="panel"><h2>Mi perfil</h2><form method="post" action="index.php?accion=actualizar-perfil"><div class="field"><label for="nombre">Nombre completo</label><input required id="nombre" name="nombre_completo" maxlength="255" value="<?= $esc($usuario['nombre_completo']) ?>"></div><div class="field"><label for="correo">Correo electrónico</label><input required id="correo" type="email" name="correo" maxlength="255" value="<?= $esc($usuario['correo']) ?>"></div><div class="field"><label for="telefono">Teléfono</label><input id="telefono" name="telefono" value="<?= $esc($usuario['telefono']??'') ?>"></div><button class="btn" type="submit">Guardar perfil</button></form></section>
<section class="panel"><h2>Accesos</h2><p class="muted">Accede a las funciones que ya existen en Fruta Madre.</p><div class="links"><a class="btn alt" href="index.php?accion=catalogo">Comprar productos</a><a class="btn alt" href="index.php?accion=eventos">Reservar evento</a><a class="btn alt" href="index.php?accion=mis-pedidos">Historial de pedidos</a><?php if(($usuario['rol']??'')==='admin'): ?><a class="btn pink" href="index.php?accion=admin-productos">Administración Stitch</a><a class="btn alt" href="index.php?accion=admin-pedidos">Gestionar pedidos</a><?php endif; ?></div></section>
<section class="panel" id="pedidos"><h2>Mis pedidos (<?= count($misPedidos) ?> recientes)</h2><?php if(!$misPedidos): ?><p class="muted">Todavía no has realizado pedidos.</p><a class="btn alt" href="index.php?accion=catalogo">Ir al catálogo</a><?php endif; ?><?php foreach($misPedidos as $p): ?><div class="row"><span><b>Pedido #<?= (int)$p['id_pedido'] ?></b><br><small><?= $esc($p['fecha_pedido']) ?> · <?= $esc($p['estado_pedido']) ?></small></span><b>$<?= number_format((float)$p['total'],2) ?> MXN</b></div><?php endforeach; ?></section>
<section class="panel" id="reservas"><h2>Mis eventos</h2><?php if(!$misEventos): ?><p class="muted">Todavía no tienes eventos reservados.</p><a class="btn alt" href="index.php?accion=eventos">Ver paquetes disponibles</a><?php endif; ?><?php foreach($misEventos as $ev): ?><div class="row"><span><b><?= $esc($ev['nombre_paquete']) ?></b><br><small><?= $esc($ev['fecha_hora']) ?> · <?= $esc($ev['tipo_evento']) ?></small></span><span><?= $esc($ev['estado_reserva']??'Registrado') ?></span></div><?php endforeach; ?></section>
<section class="panel full"><h2>Direcciones guardadas</h2><?php if(!$misDirecciones): ?><p class="muted">No tienes direcciones registradas. Podrás proporcionar la dirección durante el pedido o la reserva.</p><?php endif; ?><?php foreach($misDirecciones as $d): ?><div class="row"><span><?= $esc(implode(', ',array_filter([$d['calle_numero'],$d['colonia'],$d['ciudad'],$d['codigo_postal']]))) ?></span><small><?= $esc($d['referencias']) ?></small></div><?php endforeach; ?></section></div></main></body></html>
